#!/usr/bin/env python3
"""Applies BizPOS-specific settings to the platform folders generated by `flutter create`.

Safe to run more than once: every change checks whether it is already applied.
Run from the project root:  python3 tool/patch_platforms.py
"""
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
APP_NAME = "BizPOS"
warnings = []


def patch(path: Path, fn):
    if not path.exists():
        warnings.append(f"missing file: {path}")
        return
    old = path.read_text(encoding="utf-8")
    new = fn(old)
    if new != old:
        path.write_text(new, encoding="utf-8")
        print(f"patched {path.relative_to(ROOT)}")


# ---------------------------------------------------------------- Android
def settings_gradle(s: str) -> str:
    # mobile_scanner 6 ships Kotlin 2.1 stdlib, so the Kotlin Gradle plugin must be 2.1+.
    s = re.sub(r'(id\s+"org\.jetbrains\.kotlin\.android"\s+version\s+")[^"]+(")', r"\g<1>2.1.0\2", s)
    # CameraX 1.5 (used by mobile_scanner) needs Android Gradle plugin 8.6+.
    return re.sub(r'(id\s+"com\.android\.application"\s+version\s+")[^"]+(")', r"\g<1>8.7.3\2", s)


def gradle_wrapper(s: str) -> str:
    return re.sub(r"gradle-[0-9.]+-(all|bin)\.zip", "gradle-8.10.2-all.zip", s)


def app_gradle(s: str) -> str:
    s = re.sub(r"compileSdk\s*=\s*flutter\.compileSdkVersion", "compileSdk = 35", s)
    s = re.sub(r"minSdk\s*=\s*flutter\.minSdkVersion", "minSdk = 23", s)
    s = re.sub(r"minSdkVersion\s+flutter\.minSdkVersion", "minSdkVersion 23", s)
    if "keystoreProperties" not in s:
        header = (
            "def keystoreProperties = new Properties()\n"
            "def keystorePropertiesFile = rootProject.file('key.properties')\n"
            "if (keystorePropertiesFile.exists()) {\n"
            "    keystoreProperties.load(new FileInputStream(keystorePropertiesFile))\n"
            "}\n\n"
        )
        s = s.replace("android {", header + "android {", 1)
        signing = (
            "    signingConfigs {\n"
            "        release {\n"
            "            if (keystorePropertiesFile.exists()) {\n"
            "                keyAlias keystoreProperties['keyAlias']\n"
            "                keyPassword keystoreProperties['keyPassword']\n"
            "                storeFile file(keystoreProperties['storeFile'])\n"
            "                storePassword keystoreProperties['storePassword']\n"
            "            }\n"
            "        }\n"
            "    }\n\n"
            "    buildTypes {"
        )
        if "    buildTypes {" in s:
            s = s.replace("    buildTypes {", signing, 1)
        else:
            warnings.append("buildTypes block not found in app/build.gradle")
        s = s.replace(
            "signingConfig = signingConfigs.debug",
            "signingConfig = keystorePropertiesFile.exists() ? signingConfigs.release : signingConfigs.debug",
        )
    # flutter_local_notifications needs Java 8+ API desugaring.
    if "coreLibraryDesugaringEnabled" not in s:
        s = re.sub(r"(compileOptions\s*\{)", r"\1\n        coreLibraryDesugaringEnabled = true", s, count=1)
    if "desugar_jdk_libs" not in s:
        s += "\ndependencies {\n    coreLibraryDesugaring 'com.android.tools:desugar_jdk_libs:2.1.4'\n}\n"
    return s


ANDROID_PERMISSIONS = [
    '<uses-permission android:name="android.permission.INTERNET"/>',
    '<uses-permission android:name="android.permission.ACCESS_NETWORK_STATE"/>',
    '<uses-permission android:name="android.permission.CAMERA"/>',
    '<uses-permission android:name="android.permission.RECORD_AUDIO"/>',
    '<uses-permission android:name="android.permission.POST_NOTIFICATIONS"/>',
    '<uses-permission android:name="android.permission.USE_BIOMETRIC"/>',
    '<uses-permission android:name="android.permission.BLUETOOTH" android:maxSdkVersion="30"/>',
    '<uses-permission android:name="android.permission.BLUETOOTH_ADMIN" android:maxSdkVersion="30"/>',
    '<uses-permission android:name="android.permission.ACCESS_FINE_LOCATION" android:maxSdkVersion="30"/>',
    '<uses-permission android:name="android.permission.BLUETOOTH_CONNECT"/>',
    '<uses-permission android:name="android.permission.BLUETOOTH_SCAN" android:usesPermissionFlags="neverForLocation"/>',
    '<uses-feature android:name="android.hardware.camera" android:required="false"/>',
    '<uses-feature android:name="android.hardware.bluetooth" android:required="false"/>',
    '<uses-feature android:name="android.hardware.microphone" android:required="false"/>',
]

ANDROID_QUERIES = """    <queries>
        <intent>
            <action android:name="android.speech.RecognitionService"/>
        </intent>
        <intent>
            <action android:name="android.intent.action.VIEW"/>
            <data android:scheme="https"/>
        </intent>
        <intent>
            <action android:name="android.intent.action.SENDTO"/>
            <data android:scheme="sms"/>
        </intent>
        <intent>
            <action android:name="android.intent.action.DIAL"/>
            <data android:scheme="tel"/>
        </intent>
    </queries>
"""


def manifest(s: str) -> str:
    for perm in ANDROID_PERMISSIONS:
        name = re.search(r'android:name="([^"]+)"', perm).group(1)
        if f'"{name}"' not in s:
            s = s.replace("<application", perm + "\n    <application", 1)
    # Ads were removed from BizPOS: drop the old AdMob app id if present.
    s = re.sub(r'\s*<meta-data android:name="com\.google\.android\.gms\.ads\.APPLICATION_ID"\s*android:value="[^"]*"\s*/>', "", s)
    if "android.speech.RecognitionService" not in s:
        if "<queries>" in s:
            s = s.replace("<queries>", ANDROID_QUERIES.strip().replace("</queries>", "").replace("<queries>", "<queries>", 1), 1)
        else:
            s = s.replace("</manifest>", ANDROID_QUERIES + "</manifest>", 1)
    s = re.sub(r'android:label="[^"]*"', f'android:label="{APP_NAME}"', s, count=1)
    return s


# ---------------------------------------------------------------- iOS
# From GoogleService-Info.plist (CLIENT_ID).
IOS_GOOGLE_CLIENT_ID = "63118621975-gd1qkahehp81o2keffmv8sii9jrk6r90.apps.googleusercontent.com"

IOS_KEYS = {
    "NSCameraUsageDescription": "The camera is used to scan product barcodes and take product photos.",
    "NSMicrophoneUsageDescription": "The microphone is used for voice stock updates.",
    "NSSpeechRecognitionUsageDescription": "Speech recognition turns voice commands into stock updates.",
    "NSPhotoLibraryUsageDescription": "Photos are used as product images.",
    "NSFaceIDUsageDescription": "Face ID unlocks BizPOS instead of typing your PIN.",
    "NSBluetoothAlwaysUsageDescription": "Bluetooth is used to print receipts on thermal printers.",
    "NSBluetoothPeripheralUsageDescription": "Bluetooth is used to print receipts on thermal printers.",
}


def info_plist(s: str) -> str:
    additions = ""
    for key, value in IOS_KEYS.items():
        if key not in s:
            additions += f"\t<key>{key}</key>\n\t<string>{value}</string>\n"
    s = re.sub(r"\s*<key>GADApplicationIdentifier</key>\s*<string>[^<]*</string>", "", s)
    # Google sign-in on iOS: client id and the reversed client id URL scheme.
    if "GIDClientID" not in s:
        additions += f"\t<key>GIDClientID</key>\n\t<string>{IOS_GOOGLE_CLIENT_ID}</string>\n"
    if "CFBundleURLTypes" not in s:
        reversed_id = "com.googleusercontent.apps." + IOS_GOOGLE_CLIENT_ID.split(".apps.googleusercontent.com")[0]
        additions += (
            "\t<key>CFBundleURLTypes</key>\n\t<array>\n\t\t<dict>\n"
            "\t\t\t<key>CFBundleTypeRole</key>\n\t\t\t<string>Editor</string>\n"
            "\t\t\t<key>CFBundleURLSchemes</key>\n\t\t\t<array>\n"
            f"\t\t\t\t<string>{reversed_id}</string>\n\t\t\t</array>\n\t\t</dict>\n\t</array>\n"
        )
    if "LSApplicationQueriesSchemes" not in s:
        additions += (
            "\t<key>LSApplicationQueriesSchemes</key>\n\t<array>\n"
            "\t\t<string>whatsapp</string>\n\t\t<string>https</string>\n"
            "\t\t<string>tel</string>\n\t\t<string>sms</string>\n\t</array>\n"
        )
    if additions:
        idx = s.rfind("</dict>")
        s = s[:idx] + additions + s[idx:]
    s = re.sub(
        r"(<key>CFBundleDisplayName</key>\s*<string>)[^<]*(</string>)", rf"\g<1>{APP_NAME}\2", s
    )
    return s


PODFILE = """platform :ios, '15.5'

# CocoaPods analytics sends network stats synchronously affecting flutter build latency.
ENV['COCOAPODS_DISABLE_STATS'] = 'true'

project 'Runner', {
  'Debug' => :debug,
  'Profile' => :release,
  'Release' => :release,
}

def flutter_root
  generated_xcode_build_settings_path = File.expand_path(File.join('..', 'Flutter', 'Generated.xcconfig'), __FILE__)
  unless File.exist?(generated_xcode_build_settings_path)
    raise "#{generated_xcode_build_settings_path} must exist. If you're running pod install manually, make sure flutter pub get is executed first"
  end

  File.foreach(generated_xcode_build_settings_path) do |line|
    matches = line.match(/FLUTTER_ROOT\\=(.*)/)
    return matches[1].strip if matches
  end
  raise "FLUTTER_ROOT not found in #{generated_xcode_build_settings_path}. Try deleting Generated.xcconfig, then run flutter pub get"
end

require File.expand_path(File.join('packages', 'flutter_tools', 'bin', 'podhelper'), flutter_root)

flutter_ios_podfile_setup

target 'Runner' do
  use_frameworks!
  use_modular_headers!

  flutter_install_all_ios_pods File.dirname(File.realpath(__FILE__))
  target 'RunnerTests' do
    inherit! :search_paths
  end
end

post_install do |installer|
  installer.pods_project.targets.each do |target|
    flutter_additional_ios_build_settings(target)
    target.build_configurations.each do |config|
      config.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '15.5'
      config.build_settings['GCC_PREPROCESSOR_DEFINITIONS'] ||= [
        '$(inherited)',
        'PERMISSION_CAMERA=1',
        'PERMISSION_PHOTOS=1',
        'PERMISSION_BLUETOOTH=1',
      ]
    end
  end
end
"""


def main_activity(s: str) -> str:
    # local_auth (fingerprint unlock) needs a FragmentActivity.
    s = s.replace("import io.flutter.embedding.android.FlutterActivity", "import io.flutter.embedding.android.FlutterFragmentActivity")
    s = re.sub(r":\s*FlutterActivity\(\)", ": FlutterFragmentActivity()", s)
    return s


def main():
    android = ROOT / "android"
    if android.exists():
        patch(android / "settings.gradle", settings_gradle)
        patch(android / "gradle" / "wrapper" / "gradle-wrapper.properties", gradle_wrapper)
        patch(android / "app" / "build.gradle", app_gradle)
        patch(android / "app" / "src" / "main" / "AndroidManifest.xml", manifest)
        for kt in (android / "app" / "src" / "main").rglob("MainActivity.kt"):
            patch(kt, main_activity)
    ios = ROOT / "ios"
    if ios.exists():
        patch(ios / "Runner" / "Info.plist", info_plist)
        # mobile_scanner 6 (MLKit 7) needs iOS 15.5.
        patch(ios / "Runner.xcodeproj" / "project.pbxproj",
              lambda s: re.sub(r"IPHONEOS_DEPLOYMENT_TARGET = [0-9.]+;", "IPHONEOS_DEPLOYMENT_TARGET = 15.5;", s))
        podfile = ios / "Podfile"
        if not podfile.exists() or "platform :ios, '15.5'" not in podfile.read_text(encoding="utf-8"):
            podfile.write_text(PODFILE, encoding="utf-8")
            print("wrote ios/Podfile")
    for w in warnings:
        print("WARNING:", w)
    return 0


if __name__ == "__main__":
    sys.exit(main())
